begin;
create temporary table office_fixture(key text primary key,value text);
create temporary table office_results(test text primary key,passed boolean not null check(passed));
grant all on office_fixture,office_results to authenticated;
select set_config('request.jwt.claims',jsonb_build_object('sub',(select value from office_fixture where key='office_uid'),'role','authenticated')::text,true);
set local role authenticated;
update public.jobs set app_data='{"parts_paid_by":"company"}',internal_notes='Secretary note' where id=(select value from office_fixture where key='job');
update public.invoices set payments='[{"amount":100,"method":"Cash"}]',app_data='{"notes":"Office billing"}' where id=(select value from office_fixture where key='invoice');
update public.products set app_data='{"reorder_point":5}',rate=20 where id=(select value from office_fixture where key='product');
select public.adjust_product_stock('qa_adjust_'||gen_random_uuid()::text,(select value from office_fixture where key='product'),3,'manual','QA office receipt');
update public.purchase_orders set status='ordered',app_data='{"number":"QA","notes":"Office order"}' where id=(select value from office_fixture where key='po');
update public.tasks set app_data='{"notes":"Call customer"}' where id=(select value from office_fixture where key='task');
update public.gallery_projects set app_data='{"reference_product_id":"QA"}' where id=(select value from office_fixture where key='photo');
update public.social_posts set status='ready' where id=(select value from office_fixture where key='social');
do $$begin
 begin update public.social_posts set status='posted_manual' where id=(select value from office_fixture where key='social');raise exception 'TEST_FAILED unconfirmed publish';exception when check_violation then null;end;
 update public.team set phone='+12025550149',commission_percent=35 where id=(select value from office_fixture where key='tech');
 begin update public.team set role='owner' where id=(select value from office_fixture where key='tech');raise exception 'TEST_FAILED role escalation';exception when others then if sqlerrm not like '%contact details%' then raise;end if;end;
 begin update public.team set auth_user_id=null where id=(select value from office_fixture where key='tech');raise exception 'TEST_FAILED auth unlink';exception when others then if sqlerrm not like '%contact details%' then raise;end if;end;
 begin perform public.remove_team_member((select value from office_fixture where key='tech'));raise exception 'TEST_FAILED remove account';exception when others then if sqlerrm not like '%Only the owner%' then raise;end if;end;
 update public.team set role='owner' where id=(select value from office_fixture where key='office');
end$$;
select set_config('request.jwt.claims',jsonb_build_object('sub',(select value from office_fixture where key='tech_uid'),'role','authenticated')::text,true);
do $$begin
 begin perform public.get_office_settings();raise exception 'TEST_FAILED settings leaked';exception when others then if sqlerrm not like '%Office access required%' then raise;end if;end;
end$$;
reset role;
select jsonb_build_object('passed',count(*),'tests',jsonb_agg(test)) from office_results;
rollback;
